def _new_card(name, cost, card_type, value, rule, description, **params):
    """Cria uma definição sem ID de sprite para as cartas ainda sem arte."""
    card_id = name.casefold().replace(' ', '_')
    return (card_id, name, cost, card_type, value, rule, 'self', description, params)


